/// Computes token-level match rate against the reference oracle.
pub fn verify_token_sequence_match(generated: &[u32], reference: &[u32]) -> f64 {
    if generated.is_empty() || reference.is_empty() {
        return 0.0;
    }

    let compare_len = generated.len().min(reference.len());
    let mut matches = 0;
    for i in 0..compare_len {
        if generated[i] == reference[i] {
            matches += 1;
        }
    }

    (matches as f64 / compare_len as f64) * 100.0
}
